"use client";

/**
 * AiTab: the AI pre-review tab of the paper page (docs/design.md §5.2, §7).
 *
 * ```tsx
 * <AiTab paperId="sch:k3f9-q2xz-7mwd/v2" />
 * ```
 *
 * A purple-accented panel with the fixed banner — *Advisory. Generated by AI
 * agents. Not a peer review.* — under which the findings are grouped by
 * agent (methodology, literature, reproducibility, integrity). Each finding
 * card carries the claim, its severity and confidence, its evidence (the
 * quoted span links to the paragraph it was copied from) and the buttons
 * *Rebut* (authors) / *Confirm* / *Wrong* (reviewers) of docs/design.md §5.2.
 *
 * The panel never borrows the colours of human review status
 * (docs/design.md §1): the purple is the whole identity, a reviewer's verdict
 * is carried by its icon and word, and the banner stays above the findings
 * whatever else is loading or missing, because it qualifies everything below
 * it.
 *
 * Who may press which button is the API's call, not the tab's (the trust tier
 * is a claim inside a short-lived token): a signed-out visitor is told to
 * sign in without a request being made, and a signed-in reader the API
 * refuses hears the API's own words ("Only a paper author may rebut an AI
 * finding."). A posted answer is followed by a reload, so the reply or the
 * verdict appears beside its finding the way the report serves it.
 *
 * `/ai/{id}[/v{n}]` shows the same tab on a page of its own.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import type { FormEvent } from "react";

import { tokenStore } from "../../lib/api";
import { EmptyState, Icon } from "../ui-kit";
import {
  ADVISORY_BANNER,
  agentTitle,
  confidenceLabel,
  evidenceAnchor,
  evidenceLabel,
  findingCount,
  findingCountLabel,
  severityLabel,
  verdictLabel,
  type AiAgentGroup,
  type AiAssessment,
  type AiEvidence,
  type AiFinding,
  type AiReport,
  type AiRebuttal,
} from "./ai-report";
import {
  SIGNED_OUT_TO_ANSWER,
  classifyAiActionError,
  classifyAiReportError,
  loadAiReport,
  postAssessment,
  postRebuttal,
  type AiActionFailure,
  type LoadAiReport,
  type SendAssessment,
  type SendRebuttal,
} from "./ai-api";
import "./ai-tab.css";

/** What the three buttons do, and who they are for (docs/design.md §5.2). */
const BUTTON_TITLES = {
  rebut: "For the authors: dispute this finding with a written reply.",
  confirm: "For reviewers: mark this finding confirmed by a human check.",
  wrong: "For reviewers: mark this finding wrong.",
} as const;

/** The one in-flight answer, so a second click cannot double-post. */
type Sending =
  | { kind: "rebuttal"; findingId: string }
  | { kind: "assessment"; findingId: string; verdict: "confirmed" | "wrong" };

/** A per-finding note: a friendly explanation or a refused answer. */
interface Notice {
  readonly findingId: string;
  readonly tone: "info" | "error";
  readonly message: string;
}

type Phase =
  | { status: "loading" }
  | { status: "ready"; report: AiReport; refreshing: boolean }
  | { status: "missing" }
  | { status: "failed"; message: string };

export interface AiTabProps {
  /**
   * The paper whose report this is: `sch:xxxx-xxxx-xxxx`, a version id
   * (`sch:xxxx-xxxx-xxxx/v2`) or a bare short id.
   */
  paperId: string;
  /** Replace the loader, for tests or an alternate API client. */
  loadReport?: LoadAiReport;
  /** Replace the rebuttal sender, for tests. */
  sendRebuttal?: SendRebuttal;
  /** Replace the assessment sender, for tests. */
  sendAssessment?: SendAssessment;
  /**
   * Pin the sign-in state. When omitted it is read from the shared token
   * store after mount, so the first paint matches the server's signed-out
   * HTML.
   */
  signedIn?: boolean;
}

export function AiTab({
  paperId,
  loadReport,
  sendRebuttal,
  sendAssessment,
  signedIn,
}: AiTabProps) {
  const [phase, setPhase] = useState<Phase>({ status: "loading" });
  const [attempt, setAttempt] = useState(0);
  const [sessionIn, setSessionIn] = useState(false);
  const [rebutFor, setRebutFor] = useState<string | null>(null);
  const [rebutText, setRebutText] = useState("");
  const [sending, setSending] = useState<Sending | null>(null);
  const [notice, setNotice] = useState<Notice | null>(null);

  // The loaders, kept current without a new function re-triggering the load.
  const loadRef = useRef(loadReport ?? defaultLoad);
  useEffect(() => {
    loadRef.current = loadReport ?? defaultLoad;
  }, [loadReport]);

  // The token store is only readable in the browser; the answer is read after
  // mount so the first paint matches the server HTML (components/nav/session).
  useEffect(() => {
    if (signedIn !== undefined) {
      setSessionIn(signedIn);
      return;
    }
    setSessionIn(tokenStore.isAuthenticated);
    return tokenStore.subscribe(() => setSessionIn(tokenStore.isAuthenticated));
  }, [signedIn]);

  useEffect(() => {
    let cancelled = false;
    // A reload keeps the report on screen; only a first load shows the line.
    setPhase((current) =>
      current.status === "ready"
        ? { ...current, refreshing: true }
        : { status: "loading" },
    );

    loadRef.current(paperId).then(
      (report) => {
        if (!cancelled) {
          setPhase({ status: "ready", report, refreshing: false });
        }
      },
      (error: unknown) => {
        if (cancelled) {
          return;
        }
        const failure = classifyAiReportError(error);
        setPhase(
          failure.kind === "missing"
            ? { status: "missing" }
            : { status: "failed", message: failure.message },
        );
      },
    );
    return () => {
      cancelled = true;
    };
  }, [paperId, attempt]);

  const reload = useCallback(() => setAttempt((count) => count + 1), []);
  const closeRebutForm = useCallback(() => {
    setRebutFor(null);
    setRebutText("");
  }, []);

  /** The finding's note for a refused answer: the API's words, or sign-in. */
  const noteFailure = useCallback((findingId: string, failure: AiActionFailure) => {
    setNotice({
      findingId,
      tone: failure.kind === "signed-out" ? "info" : "error",
      message: failure.message,
    });
  }, []);

  /** Whether an answer may start; a signed-out visitor is told, not asked. */
  const beginAnswer = useCallback(
    (findingId: string): boolean => {
      setNotice(null);
      if (!sessionIn) {
        setNotice({ findingId, tone: "info", message: SIGNED_OUT_TO_ANSWER.message });
        return false;
      }
      return true;
    },
    [sessionIn],
  );

  const toggleRebut = useCallback(
    (findingId: string) => {
      // Closing is always allowed; opening is an answer, so it asks first.
      if (rebutFor === findingId) {
        closeRebutForm();
        return;
      }
      if (!beginAnswer(findingId)) {
        return;
      }
      setRebutFor(findingId);
      setRebutText("");
    },
    [rebutFor, closeRebutForm, beginAnswer],
  );

  const submitRebuttal = useCallback(
    (event: FormEvent<HTMLFormElement>, findingId: string, reviewCid: string) => {
      event.preventDefault();
      const text = rebutText.trim();
      if (text === "" || sending !== null || reviewCid === "") {
        return;
      }
      const send = sendRebuttal ?? defaultSendRebuttal;
      setSending({ kind: "rebuttal", findingId });
      send(reviewCid, findingId, text).then(
        () => {
          setSending(null);
          closeRebutForm();
          reload();
        },
        (error: unknown) => {
          setSending(null);
          noteFailure(findingId, classifyAiActionError(error));
        },
      );
    },
    [rebutText, sending, sendRebuttal, closeRebutForm, reload, noteFailure],
  );

  const answerAssessment = useCallback(
    (findingId: string, reviewCid: string, verdict: "confirmed" | "wrong") => {
      if (sending !== null || reviewCid === "" || !beginAnswer(findingId)) {
        return;
      }
      const send = sendAssessment ?? defaultSendAssessment;
      setSending({ kind: "assessment", findingId, verdict });
      send(reviewCid, findingId, verdict).then(
        () => {
          setSending(null);
          reload();
        },
        (error: unknown) => {
          setSending(null);
          noteFailure(findingId, classifyAiActionError(error));
        },
      );
    },
    [sending, beginAnswer, sendAssessment, reload, noteFailure],
  );

  const busy = phase.status !== "ready" || phase.refreshing;

  return (
    <section className="ai-tab" aria-label="AI pre-review" aria-busy={busy}>
      {/* The fixed banner: on every render, whatever else is loading or
          missing, because it qualifies everything below it — and always the
          design's own words (§8), never a label a node may have re-worded. */}
      <p className="ai-banner" role="note">
        {ADVISORY_BANNER}
      </p>

      {phase.status === "loading" ? (
        <p className="ai-loading" role="status">
          Loading the AI pre-review…
        </p>
      ) : null}

      {phase.status === "missing" ? (
        <div className="ai-empty">
          <EmptyState
            sentence="This paper has no AI pre-review yet. One is written after a version is listed."
            action={{ label: "Read the paper", href: paperHref(paperId) }}
          />
        </div>
      ) : null}

      {phase.status === "failed" ? (
        <div className="ai-failure" role="alert">
          <p className="ai-failure__text">{phase.message}</p>
          <button type="button" className="ai-button" onClick={reload}>
            Try again
          </button>
        </div>
      ) : null}

      {phase.status === "ready" ? (
        <>
          <p className="ai-summary">
            {phase.report.version !== null ? `Version ${phase.report.version} · ` : ""}
            {findingCountLabel(findingCount(phase.report))}
            {phase.refreshing ? " · updating…" : ""}
          </p>

          {phase.report.agents.map((group) => (
            <AgentSection
              key={group.agent}
              group={group}
              reviewCid={phase.report.reviewCid}
              sending={sending}
              notice={notice}
              rebutFor={rebutFor}
              rebutText={rebutText}
              onRebutText={setRebutText}
              onToggleRebut={toggleRebut}
              onCloseRebut={closeRebutForm}
              onSubmitRebuttal={submitRebuttal}
              onAssess={answerAssessment}
            />
          ))}

          <Provenance report={phase.report} />
        </>
      ) : null}
    </section>
  );
}

/** The default loader and senders, resolved at call time so tests can swap them. */
const defaultLoad: LoadAiReport = (paperId) => loadAiReport(paperId);
const defaultSendRebuttal: SendRebuttal = (reviewCid, findingId, text) =>
  postRebuttal({ reviewCid, findingId }, text);
const defaultSendAssessment: SendAssessment = (reviewCid, findingId, verdict) =>
  postAssessment({ reviewCid, findingId }, verdict);

/** One agent's findings. */
function AgentSection({
  group,
  reviewCid,
  sending,
  notice,
  rebutFor,
  rebutText,
  onRebutText,
  onToggleRebut,
  onCloseRebut,
  onSubmitRebuttal,
  onAssess,
}: {
  group: AiAgentGroup;
  reviewCid: string;
  sending: Sending | null;
  notice: Notice | null;
  rebutFor: string | null;
  rebutText: string;
  onRebutText: (text: string) => void;
  onToggleRebut: (findingId: string) => void;
  onCloseRebut: () => void;
  onSubmitRebuttal: (
    event: FormEvent<HTMLFormElement>,
    findingId: string,
    reviewCid: string,
  ) => void;
  onAssess: (findingId: string, reviewCid: string, verdict: "confirmed" | "wrong") => void;
}) {
  const headingId = `ai-agent-${group.agent.replace(/[^a-z0-9-]/gi, "-").toLowerCase()}`;
  return (
    <section className="ai-agent" aria-labelledby={headingId}>
      <h3 className="ai-agent__title" id={headingId}>
        {group.title}
      </h3>
      <p className="ai-agent__count">{findingCountLabel(group.findings.length)}</p>

      {group.findings.length === 0 ? (
        <p className="ai-agent__none">
          This agent ran and reported nothing — that is a result, not a gap.
        </p>
      ) : (
        <ul className="ai-agent__findings">
          {group.findings.map((finding) => (
            <FindingCard
              key={finding.id}
              finding={finding}
              reviewCid={reviewCid}
              sending={sending}
              notice={notice?.findingId === finding.id ? notice : null}
              rebutOpen={rebutFor === finding.id}
              rebutText={rebutText}
              onRebutText={onRebutText}
              onToggleRebut={() => onToggleRebut(finding.id)}
              onCloseRebut={onCloseRebut}
              onSubmitRebuttal={(event) => onSubmitRebuttal(event, finding.id, reviewCid)}
              onAssess={(verdict) => onAssess(finding.id, reviewCid, verdict)}
            />
          ))}
        </ul>
      )}
    </section>
  );
}

/** One finding: its claim, its evidence, the answers it received, the actions. */
function FindingCard({
  finding,
  reviewCid,
  sending,
  notice,
  rebutOpen,
  rebutText,
  onRebutText,
  onToggleRebut,
  onCloseRebut,
  onSubmitRebuttal,
  onAssess,
}: {
  finding: AiFinding;
  reviewCid: string;
  sending: Sending | null;
  notice: Notice | null;
  rebutOpen: boolean;
  rebutText: string;
  onRebutText: (text: string) => void;
  onToggleRebut: () => void;
  onCloseRebut: () => void;
  onSubmitRebuttal: (event: FormEvent<HTMLFormElement>) => void;
  onAssess: (verdict: "confirmed" | "wrong") => void;
}) {
  const rebutting = sending?.kind === "rebuttal" && sending.findingId === finding.id;
  const assessing =
    sending?.kind === "assessment" && sending.findingId === finding.id
      ? sending.verdict
      : null;
  const blocked = sending !== null || reviewCid === "";

  return (
    <li className="ai-finding" data-agent={finding.agent} data-severity={finding.severity}>
      <p className="ai-finding__claim">{finding.claim}</p>

      <p className="ai-finding__meta">
        <span className="ai-finding__severity">{severityLabel(finding.severity)}</span>
        <span className="ai-finding__sep" aria-hidden="true">
          ·
        </span>
        <span className="ai-finding__confidence">
          {confidenceLabel(finding.confidence)}
        </span>
        {finding.agentsDisagree ? (
          <span className="ai-finding__flag">Agents rated this differently</span>
        ) : null}
      </p>

      {finding.alsoReportedBy.length > 0 ? (
        <p className="ai-finding__also">
          Also reported by {finding.alsoReportedBy.map(agentTitle).join(", ")}
        </p>
      ) : null}

      <Evidence finding={finding} />

      {finding.rebuttals.map((rebuttal) => (
        <RebuttalView key={rebuttal.id} rebuttal={rebuttal} />
      ))}
      {finding.assessments.map((assessment) => (
        <AssessmentView key={assessment.id} assessment={assessment} />
      ))}

      <div className="ai-finding__actions">
        <button
          type="button"
          className="ai-button"
          title={BUTTON_TITLES.rebut}
          aria-expanded={rebutOpen}
          disabled={blocked}
          onClick={onToggleRebut}
        >
          Rebut
        </button>
        <button
          type="button"
          className="ai-button"
          title={BUTTON_TITLES.confirm}
          disabled={blocked}
          onClick={() => onAssess("confirmed")}
        >
          {assessing === "confirmed" ? "Confirming…" : "Confirm"}
        </button>
        <button
          type="button"
          className="ai-button"
          title={BUTTON_TITLES.wrong}
          disabled={blocked}
          onClick={() => onAssess("wrong")}
        >
          {assessing === "wrong" ? "Marking…" : "Wrong"}
        </button>
      </div>

      {rebutOpen ? (
        <form className="ai-rebut" onSubmit={(event) => onSubmitRebuttal(event)}>
          <label className="ai-rebut__label" htmlFor={`ai-rebut-${finding.id}`}>
            Your rebuttal
          </label>
          <textarea
            id={`ai-rebut-${finding.id}`}
            className="ai-rebut__text"
            value={rebutText}
            rows={3}
            placeholder="Say what the agents missed, in your own words."
            onChange={(event) => onRebutText(event.target.value)}
          />
          <div className="ai-rebut__row">
            <button
              type="submit"
              className="ai-button ai-button--primary"
              disabled={rebutting || rebutText.trim() === ""}
            >
              {rebutting ? "Sending…" : "Send rebuttal"}
            </button>
            <button
              type="button"
              className="ai-button"
              onClick={onCloseRebut}
              disabled={rebutting}
            >
              Cancel
            </button>
          </div>
          <p className="ai-rebut__hint">
            Published beside the finding as the authors&rsquo; reply.
          </p>
        </form>
      ) : null}

      {notice !== null ? (
        <p
          className={notice.tone === "error" ? "ai-finding__error" : "ai-finding__note"}
          role={notice.tone === "error" ? "alert" : "status"}
        >
          {notice.message}
        </p>
      ) : null}
    </li>
  );
}

/** The quoted span, reference or log line a finding rests on. */
function Evidence({ finding }: { finding: AiFinding }) {
  const evidence: AiEvidence = finding.evidence;
  const anchor = evidenceAnchor(evidence);
  const label = evidenceLabel(evidence);
  const value = evidence.value;

  if (value === null) {
    return (
      <p className="ai-evidence" data-kind={evidence.kind}>
        <span className="ai-evidence__label">{label}</span>
      </p>
    );
  }

  const body = (
    <>
      <span className="ai-evidence__label">{label}:</span>{" "}
      <span className="ai-evidence__value" data-kind={evidence.kind}>
        {evidence.kind === "span" ? `“${value}”` : value}
      </span>
      {anchor !== null ? (
        <span className="ai-visually-hidden"> (jumps to the quoted paragraph)</span>
      ) : null}
    </>
  );

  // Only a span with its paragraph id has somewhere to jump; anything else
  // would be a dead link, so it is shown as plain text.
  if (anchor !== null) {
    return (
      <a className="ai-evidence" href={anchor} data-kind={evidence.kind}>
        {body}
      </a>
    );
  }
  return (
    <p className="ai-evidence" data-kind={evidence.kind}>
      {body}
    </p>
  );
}

/** An author's reply, shown beside the finding it answers. */
function RebuttalView({ rebuttal }: { rebuttal: AiRebuttal }) {
  return (
    <div className="ai-response" data-kind="rebuttal">
      <p className="ai-response__kind">Author rebuttal</p>
      <p className="ai-response__text">{rebuttal.text}</p>
    </div>
  );
}

/** A reviewer's verdict: the icon and the word carry it, never colour alone. */
function AssessmentView({ assessment }: { assessment: AiAssessment }) {
  const confirmed = assessment.verdict === "confirmed";
  return (
    <div className="ai-response" data-kind="assessment" data-verdict={assessment.verdict}>
      <p className="ai-response__kind">
        <Icon
          name={confirmed ? "check" : "cross"}
          className={confirmed ? "ai-response__icon" : "ai-response__icon ai-response__icon--wrong"}
        />
        {verdictLabel(assessment.verdict)}
      </p>
    </div>
  );
}

/** Models, prompt set and record id — the reproducibility footnotes. */
function Provenance({ report }: { report: AiReport }) {
  return (
    <details className="ai-provenance">
      <summary className="ai-provenance__summary">How this was generated</summary>
      <p className="ai-provenance__note">
        Generated by AI agents from public prompts once the version was listed.
        It advises; it never decides anything about the paper.
      </p>
      {report.models.length > 0 ? (
        <ul className="ai-provenance__models">
          {report.models.map((model, index) => (
            <li key={`${index}:${model.name ?? "?"}`}>
              {model.name ?? "unknown model"}
              {model.provider !== null ? ` (${model.provider})` : ""}
              {model.version !== null && model.version !== model.name ? (
                <>
                  {" "}
                  <span className="ai-provenance__version">{model.version}</span>
                </>
              ) : null}
            </li>
          ))}
        </ul>
      ) : null}
      <dl className="ai-provenance__facts">
        {report.promptSetHash !== null ? (
          <div className="ai-provenance__row">
            <dt>Prompt set</dt>
            <dd className="mono-id">{report.promptSetHash}</dd>
          </div>
        ) : null}
        {report.reviewCid !== "" ? (
          <div className="ai-provenance__row">
            <dt>Review record</dt>
            <dd className="mono-id">{report.reviewCid}</dd>
          </div>
        ) : null}
      </dl>
    </details>
  );
}

/** `/p/{id}`: the paper page's path, from any id spelling this tab accepts. */
export function paperHref(paperId: string): string {
  return `/p/${paperId.trim().replace(/^sch:/i, "")}`;
}
